BEGIN;
ALTER TABLE public.pessoas ADD COLUMN IF NOT EXISTS google_contact_id text DEFAULT NULL, ADD COLUMN IF NOT EXISTS google_sync_enabled boolean DEFAULT true, ADD COLUMN IF NOT EXISTS google_synced_at timestamptz DEFAULT NULL;
ALTER TABLE public.pessoas ADD COLUMN IF NOT EXISTS cadastro_automatico boolean DEFAULT false, ADD COLUMN IF NOT EXISTS origem_cadastro text DEFAULT NULL, ADD COLUMN IF NOT EXISTS revisao_pendente boolean DEFAULT false, ADD COLUMN IF NOT EXISTS ultimo_match_extrato timestamptz DEFAULT NULL, ADD COLUMN IF NOT EXISTS total_matchs_extrato integer DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS idx_pessoas_google_contact_id ON public.pessoas(google_contact_id) WHERE google_contact_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pessoas_cadastro_automatico ON public.pessoas(cadastro_automatico) WHERE cadastro_automatico = true;
CREATE INDEX IF NOT EXISTS idx_pessoas_revisao_pendente ON public.pessoas(revisao_pendente) WHERE revisao_pendente = true;
CREATE OR REPLACE VIEW public.vw_contatos_reais AS SELECT * FROM public.pessoas WHERE (cadastro_automatico IS NULL OR cadastro_automatico = false) AND ativo = true;
CREATE OR REPLACE VIEW public.vw_cadastros_google_sync AS SELECT id,nome,email,telefone,tipo,empresa,cargo,cpf_cnpj,notas,cep,logradouro,numero,bairro,cidade,estado,pais,drive_link,data_inicio_wg,google_contact_id,google_sync_enabled,google_synced_at,updated_at,created_at FROM public.pessoas WHERE (cadastro_automatico IS NULL OR cadastro_automatico = false) AND (google_sync_enabled IS NULL OR google_sync_enabled = true) AND ativo = true AND nome IS NOT NULL AND length(trim(nome)) >= 2;
CREATE OR REPLACE VIEW public.vw_cadastros_pendentes_revisao AS SELECT id,nome,tipo,cpf_cnpj,origem_cadastro,ultimo_match_extrato,total_matchs_extrato,created_at,updated_at FROM public.pessoas WHERE cadastro_automatico = true AND (revisao_pendente IS NULL OR revisao_pendente = true) AND ativo = true ORDER BY total_matchs_extrato DESC NULLS LAST, created_at DESC;
CREATE OR REPLACE FUNCTION public.fn_promover_para_contato_real(p_pessoa_id uuid, p_tipo text DEFAULT NULL, p_email text DEFAULT NULL, p_telefone text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN UPDATE public.pessoas SET cadastro_automatico=false, revisao_pendente=false, tipo=COALESCE(p_tipo,tipo), email=COALESCE(p_email,email), telefone=COALESCE(p_telefone,telefone), updated_at=now() WHERE id=p_pessoa_id AND cadastro_automatico=true; IF NOT FOUND THEN RAISE EXCEPTION 'Pessoa nao encontrada ou nao automatica: %', p_pessoa_id; END IF; END; $$;
UPDATE public.pessoas SET cadastro_automatico = false WHERE cadastro_automatico IS NULL;
COMMIT;
